param([Parameter(Mandatory=$true)][string]$PackageRoot,[Parameter(Mandatory=$true)][string]$RequestPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version 2.0
$PackageRoot=([string]$PackageRoot).Trim().Trim([char[]]@([char]34));$PackageRoot=(Get-Item -LiteralPath $PackageRoot -Force -ErrorAction Stop).FullName
. (Join-Path $PackageRoot 'Modules\Forge.ImageValidation.ps1')
function V($o,[string]$n){if($null-eq$o){return $null};$p=$o.PSObject.Properties[$n];if($null-eq$p){return $null};return $p.Value}
function Sha([string]$p){return (Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function WriteJsonAtomic([string]$p,$o){$tmp=$p+'.tmp.'+[Guid]::NewGuid().ToString('N');$utf8=New-Object Text.UTF8Encoding -ArgumentList $false;[IO.File]::WriteAllText($tmp,($o|ConvertTo-Json -Depth 30),$utf8);Move-Item -LiteralPath $tmp -Destination $p -Force}
$stateRoot=Join-Path $env:LOCALAPPDATA 'MerchForge';$spool=Join-Path $stateRoot 'check-spool-v1';$reqRoot=[IO.Path]::GetFullPath((Join-Path $spool 'requests'));if(-not$reqRoot.EndsWith([string][IO.Path]::DirectorySeparatorChar,[StringComparison]::Ordinal)){$reqRoot+=[IO.Path]::DirectorySeparatorChar};$full=[IO.Path]::GetFullPath($RequestPath);if(-not$full.StartsWith($reqRoot,[StringComparison]::OrdinalIgnoreCase)){throw 'Check request path is outside trusted spool.'}
$req=Get-Content -LiteralPath $full -Raw -Encoding UTF8|ConvertFrom-Json;if([string](V $req 'schema')-ne'forge.check_worker_request.v1'){throw 'Unsupported check-worker request.'};if([string](V $req 'worker_sha256') -ne (Sha $PSCommandPath)){throw 'Check-worker request is stale for this worker version.'};$requestId=[string](V $req 'request_id');if($requestId-notmatch'^worker-check-[0-9a-f]{24}$'){throw 'Invalid check-worker request id.'};$art=[string](V $req 'artwork_path');$want=([string](V $req 'artwork_sha256')).ToLowerInvariant();if(-not(Test-Path -LiteralPath $art -PathType Leaf) -or $want-notmatch'^[0-9a-f]{64}$' -or (Sha $art)-ne$want){throw 'Accepted artwork failed exact SHA verification.'}
$bytes=[IO.File]::ReadAllBytes($art);$native=$false;$reason='not_png';$w=0;$h=0;$ext=[IO.Path]::GetExtension($art).ToLowerInvariant();if($ext-eq'.png'){try{$meta=Get-ForgePngMetadata $bytes;if(-not[bool](V $meta 'valid')){throw 'invalid_png'};$w=[int](V $meta 'width');$h=[int](V $meta 'height');$png=Test-ForgeGenerationPngFile $art $w $h;$native=[bool](V $png 'ok');$reason=[string](V $png 'reason')}catch{throw ('Artwork PNG decode/validation failed: '+$_.Exception.Message)}}elseif($ext-in@('.jpg','.jpeg')){$reason='trusted_print_worker_requires_transparent_png'}else{throw 'Unsupported accepted artwork format.'}
$profile=$null;$profileStatus='missing_or_expired';$profilePath=[string](V $req 'channel_profile_path');$profileSourceSha='';$refs=@();$profileValid=$false
if(-not[string]::IsNullOrWhiteSpace($profilePath) -and (Test-Path -LiteralPath $profilePath -PathType Leaf) -and [string](V $req 'channel_profile_sha256') -eq (Sha $profilePath)){
 try{$profile=Get-Content -LiteralPath $profilePath -Raw -Encoding UTF8|ConvertFrom-Json;$capt=[DateTime]::Parse([string](V $profile 'captured_at')).ToUniversalTime();$vu=[DateTime]::Parse([string](V $profile 'valid_until')).ToUniversalTime();$refs=@(V $profile 'source_refs');$profileSourceSha=[string](V $profile 'source_file_sha256');$refsValid=($refs.Count-ge1);foreach($rr in $refs){try{$uu=[Uri][string]$rr;$hh=$uu.Host.ToLowerInvariant();if($uu.Scheme-ne'https' -or $hh-notin@('developer.amazon.com','merch.amazon.com','sellercentral.amazon.com')){$refsValid=$false}}catch{$refsValid=$false}};$profileValid=([string](V $profile 'schema')-eq'forge.amazon_print_profile.v1' -and [bool](V $profile 'attested') -eq $true -and [string](V $profile 'authority_kind')-eq'owner_attested_external' -and [bool](V $profile 'independent_verification')-eq$false -and $capt-le[DateTime]::UtcNow.AddMinutes(10) -and $vu-gt[DateTime]::UtcNow -and $vu-gt$capt -and ($vu-$capt).TotalDays-le120 -and [int](V $profile 'canvas_width_px')-ge500 -and [int](V $profile 'canvas_width_px')-le10000 -and [int](V $profile 'canvas_height_px')-ge500 -and [int](V $profile 'canvas_height_px')-le10000 -and [int](V $profile 'dpi')-ge72 -and [int](V $profile 'dpi')-le600 -and [string](V $profile 'file_format')-eq'png' -and [string](V $profile 'background')-eq'transparent' -and [string](V $profile 'template_file_sha256')-match'^[0-9a-f]{64}$' -and $profileSourceSha-match'^[0-9a-f]{64}$' -and $refsValid -and -not[string]::IsNullOrWhiteSpace([string](V $profile 'marketplace')) -and -not[string]::IsNullOrWhiteSpace([string](V $profile 'product_type_key')) -and -not[string]::IsNullOrWhiteSpace([string](V $profile 'template_key')));if($profileValid){$profileStatus='owner_attested_current'}}catch{}
}
$exact=$false;if($profileValid){$exact=($w-eq[int](V $profile 'canvas_width_px') -and $h-eq[int](V $profile 'canvas_height_px'))};$printReady=($native -and $profileValid -and $exact);$printReason=if($printReady){'Exact accepted transparent PNG matches the owner-attested current Amazon template canvas.'}elseif(-not$native){'Accepted artwork failed local PNG/transparency validation: '+$reason}elseif(-not$profileValid){'Local technical image checks passed, but no current owner-attested Amazon print profile is available.'}else{'Local technical image checks passed, but accepted artwork dimensions do not match the owner-attested Amazon template canvas.'}
$evidenceRefs=@();if($printReady){foreach($x in $refs){if(-not[string]::IsNullOrWhiteSpace([string]$x)){$evidenceRefs+=[string]$x}};$evidenceRefs+=('template_sha256:'+[string](V $profile 'template_file_sha256'));$evidenceRefs+=('artwork_sha256:'+$want)}
$resultRoot=Join-Path $spool 'results';if(-not(Test-Path $resultRoot)){New-Item -ItemType Directory -Path $resultRoot -Force|Out-Null};$resultPath=Join-Path $resultRoot ($requestId+'.result.json');$out=[ordered]@{schema='forge.check_worker_result.v1';request_id=$requestId;request_sha256=(Sha $full);worker_sha256=(Sha $PSCommandPath);concept_key=[string](V $req 'concept_key');concept_revision_id=[string](V $req 'concept_revision_id');revision_hash=[string](V $req 'revision_hash');acceptance_fingerprint=[string](V $req 'acceptance_fingerprint');artwork_sha256=$want;listing_hash=[string](V $req 'listing_hash');checked_at=[DateTime]::UtcNow.ToString('o');network_calls=0;external_submission_authorized=$false;print_production=[ordered]@{schema='forge.print_production_snapshot.v1';ready=$printReady;reason=$printReason;technical=[ordered]@{sha256=$want;width_px=$w;height_px=$h;file_size_bytes=$bytes.Length;png_native_validation=$native;png_validation_reason=$reason;max_print_width_in_at_300ppi=[Math]::Round(([double]$w/300.0),2);max_print_height_in_at_300ppi=[Math]::Round(([double]$h/300.0),2)};channel_profile_status=$profileStatus;channel_profile=if($profileValid){$profile}else{$null}};print=[ordered]@{state=if($printReady){'pass'}else{'needs_review'};authority_kind=if($printReady){'owner_attested_external'}else{'none'};note=$printReason;evidence_refs=$evidenceRefs};profile_source_file_sha256=$profileSourceSha};WriteJsonAtomic $resultPath $out;exit 0
